                    let now_slot =
                        (elapsed / crate::time::wheel::slot_range(level.level)) as usize;
                    let rotated = level.occupied.rotate_right(now_slot as u32);
                    let zeros = rotated.trailing_zeros() as usize;
                    let slot = (zeros + now_slot) % 64;
                    let range_level = crate::time::wheel::level_range(level.level);
                    let range_slot = crate::time::wheel::slot_range(level.level);
                    let level_start = elapsed - (elapsed % range_level);
                    let mut deadline = level_start + slot as u64 * range_slot;
                    if deadline < elapsed {
                        debug_assert_eq!(level.level, crate::time::wheel::NUM_LEVELS - 1);
                        deadline += range_level;
                    }
                    debug_assert!(
                        deadline >= elapsed,
                        "deadline={:016X}; now={:016X}; level={}; slot={}; occupied={:b}",
                        deadline,
                        elapsed,
                        level.level,
                        slot,
                        level.occupied
