                    let mut prior_ok = true;
                    let mut later = level_idx + 1;
                    while later < crate::time::wheel::NUM_LEVELS {
                        let later_level = &self.wheel.levels[later];
                        if later_level.occupied != 0 {
                            let later_now_slot = (elapsed
                                / crate::time::wheel::slot_range(later_level.level))
                                as usize;
                            let later_rotated =
                                later_level.occupied.rotate_right(later_now_slot as u32);
                            let later_zeros = later_rotated.trailing_zeros() as usize;
                            let later_slot = (later_zeros + later_now_slot) % 64;
                            let later_range_level =
                                crate::time::wheel::level_range(later_level.level);
                            let later_range_slot =
                                crate::time::wheel::slot_range(later_level.level);
                            let later_start = elapsed - (elapsed % later_range_level);
                            let mut later_deadline =
                                later_start + later_slot as u64 * later_range_slot;
                            if later_deadline < elapsed {
                                debug_assert_eq!(
                                    later_level.level,
                                    crate::time::wheel::NUM_LEVELS - 1
                                );
                                later_deadline += later_range_level;
                            }
                            if later_deadline < deadline {
                                prior_ok = false;
                            }
                        }
                        later += 1;
                    }
                    debug_assert!(prior_ok);
                    found = Some(self.start + Duration::from_millis(deadline));
                }
            }
            level_idx += 1;
        }
        found
    };

    if prev_deadline != next_deadline {
        match (next_deadline, &mut self.delay) {
            (None, _) => self.delay = None,
            (Some(deadline), Some(delay)) => delay.as_mut().reset(deadline),
            (Some(deadline), None) => self.delay = Some(Box::pin(sleep_until(deadline))),
        }
    }

    Expired {
        key: Key::new(key.index),
        data: data.inner,
        deadline: self.start + Duration::from_millis(data.when),
    }
}

